export const getProfileSchema = (role, orgType) => {
  let schemaSet = SCHOOL_ROLE_SCHEMAS; // fallback
  switch (orgType) {
    case "school":
      schemaSet = SCHOOL_ROLE_SCHEMAS;
      break;
    case "engineering":
      schemaSet = ENGINEERING_ROLE_SCHEMAS;
      break;
    case "coaching":
      schemaSet = COACHING_ROLE_SCHEMAS;
      break;
    case "junior_college":
      schemaSet = JUNIOR_COLLEGE_ROLE_SCHEMAS;
      break;
    case "diploma":
      schemaSet = DIPLOMA_ROLE_SCHEMAS;
      break;
  }
  
  // Map some roles if they use aliases
  const roleMapping = {
    'org_admin': 'principal',
    'faculty': 'teacher',
    'hod': 'principal',
    'tpo_officer': 'principal',
    'admission_verifier': 'admission_head',
    'admission_counselor': 'admission_head',
    'admission_clerk': 'admission_head',
    'counselor': 'teacher',
    'hr_manager': 'hr_admin'
  };

  const lookupRole = roleMapping[role] || role;
  
  // Try directly first, then try lookup role, then fallback to student if school, else return empty
  if (schemaSet[role]) return schemaSet[role];
  if (schemaSet[lookupRole]) return schemaSet[lookupRole];
  
  return schemaSet['student'] || [];
};
